def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp_c = 0
    for _, opp in history:
        if opp == 'C':
            opp_c += 1
    opp_d = n - opp_c

    last_own, last_opp = history[-1]

    # In the final round, defect is always weakly dominant.
    if n >= 99:
        return 'D'

    # If the opponent has never defected, exploit after a short trust period.
    # This gains large score against Always C and very forgiving strategies.
    if opp_d == 0:
        if n >= 10:
            return 'D'
        return 'C'

    # If the opponent is not net cooperative, stop trying to cooperate.
    if opp_d >= opp_c:
        return 'D'

    # Measure whether our unprovoked defections are punished.
    # Punished: our D, their C, then their next move D.
    # Forgiven: our D, their C, then their next move C.
    punished = 0
    forgiven = 0
    for i in range(n - 1):
        me, opp = history[i]
        if me == 'D' and opp == 'C':
            if history[i + 1][1] == 'D':
                punished += 1
            else:
                forgiven += 1

    recent_len = n if n < 10 else 10
    recent_opp_d = 0
    for i in range(n - recent_len, n):
        if history[i][1] == 'D':
            recent_opp_d += 1

    # If they are currently mostly defecting, defend.
    if recent_len >= 4 and recent_opp_d * 2 > recent_len:
        return 'D'

    # If they have recently returned to full cooperation and either never punish
    # our D, or forgive much more often than they punish, exploit them again.
    if n >= 20 and recent_opp_d == 0 and (punished == 0 or forgiven > 2 * punished):
        return 'D'

    recent_own_len = n if n < 5 else 5
    recent_own_d = 0
    for i in range(n - recent_own_len, n):
        if history[i][0] == 'D':
            recent_own_d += 1

    # Defensive response to an opponent defection.
    if last_opp == 'D':
        # Mutual D: if the opponent is otherwise cooperative, try to reset.
        if last_own == 'D':
            return 'C'

        # If their D looks like a response to our recent D, cooperate to restore CC.
        if punished > 0 and recent_own_d > 0:
            return 'C'

        # Immediate punishment for our previous D.
        if n >= 2 and history[-2][0] == 'D' and history[-2][1] == 'C':
            return 'C'

        # Otherwise punish their defection.
        return 'D'

    # Opponent cooperated last.
    if last_own == 'D':
        # Continue a forgiving exploitation streak if behavior is clean.
        if recent_opp_d == 0 and (punished == 0 or forgiven > 2 * punished):
            return 'D'
        return 'C'

    return 'C'
